package com.amilingo.platform.module.patent.service;

import com.amilingo.platform.module.patent.dto.PatentWorkflowDTO.*;
import com.amilingo.platform.module.patent.entity.*;
import com.amilingo.platform.module.patent.repository.*;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.time.*;import java.util.*;

@Service @RequiredArgsConstructor
public class PatentWorkflowService{
 private final PatentRepository patentRepo;private final PatentDisclosureRepository disclosureRepo;private final PatentStatusHistoryRepository historyRepo;
 private final PatentProjectLinkRepository linkRepo;private final PatentMaterialCardRepository cardRepo;private final PatentInventorRepository inventorRepo;
 private static final Map<String,Set<String>> TRANSITIONS=Map.ofEntries(
  Map.entry("DISCLOSURE_DRAFT",Set.of("DISCLOSURE_REVIEW","WITHDRAWN")),Map.entry("DISCLOSURE_REVIEW",Set.of("DISCLOSURE_DRAFT","MATERIAL_PREPARATION")),
  Map.entry("MATERIAL_PREPARATION",Set.of("FILED","WITHDRAWN")),Map.entry("FILED",Set.of("ACCEPTED","WITHDRAWN")),
  Map.entry("ACCEPTED",Set.of("PRELIMINARY_EXAM","REJECTED","WITHDRAWN")),Map.entry("PRELIMINARY_EXAM",Set.of("PUBLISHED","REJECTED")),
  Map.entry("PUBLISHED",Set.of("SUBSTANTIVE_EXAM","EXPIRED")),Map.entry("SUBSTANTIVE_EXAM",Set.of("OFFICE_ACTION","GRANTED","REJECTED")),
  Map.entry("OFFICE_ACTION",Set.of("RESPONSE_SUBMITTED","REJECTED","WITHDRAWN")),Map.entry("RESPONSE_SUBMITTED",Set.of("OFFICE_ACTION","GRANTED","REJECTED")),
  Map.entry("GRANTED",Set.of("INVALID","EXPIRED")),Map.entry("REJECTED",Set.of()),Map.entry("WITHDRAWN",Set.of()),Map.entry("INVALID",Set.of()),Map.entry("EXPIRED",Set.of()));

 @Transactional public PatentDisclosure saveDisclosure(Long patentId,DisclosureRequest r){Patent p=owned(patentId,r.actorUserId());PatentDisclosure d=disclosureRepo.findByPatentId(patentId).orElseGet(()->PatentDisclosure.builder().patentId(patentId).status("DRAFT").build());
  if(!Set.of("DRAFT","RETURNED").contains(d.getStatus()))throw new IllegalStateException("当前交底状态不可编辑");
  d.setBackgroundTechnology(r.backgroundTechnology());d.setExistingProblems(r.existingProblems());d.setTechnicalProblem(r.technicalProblem());d.setTechnicalSolution(r.technicalSolution());d.setInnovations(r.innovations());d.setBeneficialEffects(r.beneficialEffects());d.setEmbodiments(r.embodiments());d.setDrawingDescription(r.drawingDescription());d.setKeyParameters(r.keyParameters());d.setAlternativeSolutions(r.alternativeSolutions());d.setTechnologyReadinessLevel(r.technologyReadinessLevel());d.setAttachments(join(r.attachments()));p.setTechnicalField(p.getTechnicalField());return disclosureRepo.save(d);}
 public PatentDisclosure getDisclosure(Long patentId,Long actor){owned(patentId,actor);return disclosureRepo.findByPatentId(patentId).orElseThrow(()->new IllegalArgumentException("技术交底不存在"));}
 @Transactional public PatentDisclosure actDisclosure(Long patentId,DisclosureActionRequest r){Patent p=patent(patentId);PatentDisclosure d=disclosureRepo.findByPatentId(patentId).orElseThrow(()->new IllegalArgumentException("技术交底不存在"));
  switch(r.action()){case"SUBMIT"->{if(!p.getUserId().equals(r.actorUserId()))throw new SecurityException("只有专利所有者可以提交交底");require(d.getStatus(),"DRAFT","RETURNED");d.setStatus("PENDING_REVIEW");d.setSubmittedBy(r.actorUserId());d.setSubmittedAt(LocalDateTime.now());updateStatus(p,"DISCLOSURE_REVIEW",r.actorUserId(),LocalDate.now(),"提交技术交底审核",null);}
   case"APPROVE"->{if(p.getUserId().equals(r.actorUserId()))throw new IllegalArgumentException("提交人不能审核自己的交底");require(d.getStatus(),"PENDING_REVIEW");d.setStatus("APPROVED");d.setReviewedBy(r.actorUserId());d.setReviewOpinion(r.opinion());d.setReviewedAt(LocalDateTime.now());updateStatus(p,"MATERIAL_PREPARATION",r.actorUserId(),LocalDate.now(),"技术交底审核通过",null);}
   case"RETURN"->{if(p.getUserId().equals(r.actorUserId()))throw new IllegalArgumentException("提交人不能审核自己的交底");require(d.getStatus(),"PENDING_REVIEW");if(r.opinion()==null||r.opinion().isBlank())throw new IllegalArgumentException("退回交底必须填写意见");d.setStatus("RETURNED");d.setReviewedBy(r.actorUserId());d.setReviewOpinion(r.opinion());d.setReviewedAt(LocalDateTime.now());updateStatus(p,"DISCLOSURE_DRAFT",r.actorUserId(),LocalDate.now(),"技术交底退回修改",null);}}
  return disclosureRepo.save(d);}

 @Transactional public Patent changeStatus(Long patentId,StatusChangeRequest r){Patent p=owned(patentId,r.actorUserId());String current=p.getStatus();if(!current.equals(r.status())&&!TRANSITIONS.getOrDefault(current,Set.of()).contains(r.status()))throw new IllegalStateException("非法状态流转: "+current+" -> "+r.status());
  if("FILED".equals(r.status())){if(r.applicationNumber()==null||r.applicationNumber().isBlank())throw new IllegalArgumentException("提交申请时必须填写申请号");p.setApplicationNumber(r.applicationNumber());p.setApplicationDate(r.effectiveDate());}
  if("GRANTED".equals(r.status())){if(r.grantNumber()==null||r.grantNumber().isBlank())throw new IllegalArgumentException("授权时必须填写授权号");p.setGrantNumber(r.grantNumber());p.setGrantDate(r.effectiveDate());}
  switch(r.status()){case"ACCEPTED"->p.setAcceptanceDate(r.effectiveDate());case"PUBLISHED"->p.setPublicationDate(r.effectiveDate());case"SUBSTANTIVE_EXAM"->p.setSubstantiveExamDate(r.effectiveDate());case"GRANTED"->p.setGrantPublicationDate(r.effectiveDate());default->{}}
  updateStatus(p,r.status(),r.actorUserId(),r.effectiveDate(),r.remark(),join(r.attachments()));return p;}
 public List<PatentStatusHistory> statusHistory(Long patentId,Long actor){owned(patentId,actor);return historyRepo.findByPatentIdOrderByEffectiveDateDescIdDesc(patentId);}

 @Transactional public PatentProjectLink linkProject(Long patentId,ProjectLinkRequest r){owned(patentId,r.actorUserId());if(linkRepo.existsByPatentIdAndResearchProjectIdAndDeliverableIdAndStatus(patentId,r.researchProjectId(),r.deliverableId(),"ACTIVE"))throw new IllegalArgumentException("该项目成果已关联");return linkRepo.save(PatentProjectLink.builder().patentId(patentId).researchProjectId(r.researchProjectId()).deliverableId(r.deliverableId()).deliverableType(r.deliverableType()).description(r.description()).linkedBy(r.actorUserId()).status("ACTIVE").build());}
 @Transactional public void unlinkProject(Long linkId,Long actor){PatentProjectLink l=linkRepo.findById(linkId).orElseThrow(()->new IllegalArgumentException("项目关联不存在"));owned(l.getPatentId(),actor);l.setStatus("REMOVED");linkRepo.save(l);}
 public List<PatentProjectLink> projectLinks(Long patentId,Long actor){owned(patentId,actor);return linkRepo.findByPatentIdAndStatusOrderByCreatedAtDesc(patentId,"ACTIVE");}

 @Transactional public PatentMaterialCard createCard(Long patentId,MaterialCardRequest r){owned(patentId,r.actorUserId());validateSource(patentId,r.sourceType(),r.sourceId());int no=cardRepo.findFirstByPatentIdOrderByCardNoDesc(patentId).map(x->x.getCardNo()+1).orElse(1);return cardRepo.save(toCard(patentId,no,1,r));}
 @Transactional public List<PatentMaterialCard> generateCardsFromDisclosure(Long patentId,MaterialCardGenerationRequest r){owned(patentId,r.actorUserId());PatentDisclosure d=disclosureRepo.findByPatentId(patentId).orElseThrow(()->new IllegalArgumentException("请先登记技术交底"));if(!"APPROVED".equals(d.getStatus()))throw new IllegalStateException("技术交底审核通过后才能生成素材卡");List<PatentMaterialCard> result=new ArrayList<>();
  result.add(createCard(patentId,new MaterialCardRequest(r.actorUserId(),"PROBLEM","技术问题",d.getTechnicalProblem(),null,null,null,null,null,null,null,"DISCLOSURE",d.getId())));
  result.add(createCard(patentId,new MaterialCardRequest(r.actorUserId(),"SOLUTION","技术方案",d.getTechnicalProblem(),d.getTechnicalSolution(),null,null,d.getBeneficialEffects(),d.getDrawingDescription(),null,null,"DISCLOSURE",d.getId())));
  result.add(createCard(patentId,new MaterialCardRequest(r.actorUserId(),"INNOVATION","创新点",null,null,d.getInnovations(),null,d.getBeneficialEffects(),null,null,null,"DISCLOSURE",d.getId())));return result;}
 @Transactional public PatentMaterialCard reviseCard(Long cardId,MaterialCardRequest r){PatentMaterialCard source=cardRepo.findById(cardId).orElseThrow(()->new IllegalArgumentException("素材卡不存在"));owned(source.getPatentId(),r.actorUserId());validateSource(source.getPatentId(),r.sourceType(),r.sourceId());List<PatentMaterialCard> versions=cardRepo.findByPatentIdAndCardNoOrderByVersionNoDesc(source.getPatentId(),source.getCardNo());versions.stream().filter(PatentMaterialCard::getCurrentVersion).forEach(x->{x.setCurrentVersion(false);cardRepo.save(x);});int next=versions.stream().mapToInt(PatentMaterialCard::getVersionNo).max().orElse(0)+1;return cardRepo.save(toCard(source.getPatentId(),source.getCardNo(),next,r));}
 public List<PatentMaterialCard> cards(Long patentId,Long actor){owned(patentId,actor);return cardRepo.findByPatentIdAndCurrentVersionTrueOrderByCardNoAsc(patentId);}
 public List<PatentMaterialCard> cardVersions(Long patentId,Integer cardNo,Long actor){owned(patentId,actor);return cardRepo.findByPatentIdAndCardNoOrderByVersionNoDesc(patentId,cardNo);}

 @Transactional public PatentInventor addInventor(Long patentId,InventorRequest r){owned(patentId,r.actorUserId());if(inventorRepo.existsByPatentIdAndInventorOrder(patentId,r.inventorOrder()))throw new IllegalArgumentException("发明人顺序已占用");PatentInventor i=inventorRepo.save(toInventor(patentId,r));syncLegacyOrder(patentId);return i;}
 @Transactional public PatentInventor updateInventor(Long id,InventorRequest r){PatentInventor i=inventorRepo.findById(id).orElseThrow(()->new IllegalArgumentException("发明人不存在"));owned(i.getPatentId(),r.actorUserId());if(!i.getInventorOrder().equals(r.inventorOrder())&&inventorRepo.existsByPatentIdAndInventorOrder(i.getPatentId(),r.inventorOrder()))throw new IllegalArgumentException("发明人顺序已占用");i.setUserId(r.userId());i.setName(r.name());i.setInstitution(r.institution());i.setInventorOrder(r.inventorOrder());i.setFirstInventor(Boolean.TRUE.equals(r.firstInventor())||r.inventorOrder()==1);i.setContribution(r.contribution());i.setContactEmail(r.contactEmail());i.setContactPhone(r.contactPhone());PatentInventor saved=inventorRepo.save(i);syncLegacyOrder(i.getPatentId());return saved;}
 @Transactional public PatentInventor confirmInventor(Long id,InventorConfirmationRequest r){PatentInventor i=inventorRepo.findById(id).orElseThrow(()->new IllegalArgumentException("发明人不存在"));if(i.getUserId()!=null&&!i.getUserId().equals(r.actorUserId()))throw new SecurityException("只能确认本人的发明人信息");i.setConfirmationStatus(r.status());i.setConfirmedAt("CONFIRMED".equals(r.status())?LocalDateTime.now():null);return inventorRepo.save(i);}
 @Transactional public void deleteInventor(Long id,Long actor){PatentInventor i=inventorRepo.findById(id).orElseThrow(()->new IllegalArgumentException("发明人不存在"));owned(i.getPatentId(),actor);if("CONFIRMED".equals(i.getConfirmationStatus()))throw new IllegalArgumentException("已确认发明人不能直接删除");inventorRepo.delete(i);syncLegacyOrder(i.getPatentId());}
 public List<PatentInventor> inventors(Long patentId,Long actor){owned(patentId,actor);return inventorRepo.findByPatentIdOrderByInventorOrderAsc(patentId);}

 private void updateStatus(Patent p,String status,Long actor,LocalDate date,String remark,String attachments){String previous=p.getStatus();p.setStatus(status);patentRepo.save(p);if(!Objects.equals(previous,status))historyRepo.save(PatentStatusHistory.builder().patentId(p.getId()).previousStatus(previous).currentStatus(status).effectiveDate(date).operatorUserId(actor).remark(remark).attachments(attachments).build());}
 private Patent owned(Long id,Long actor){Patent p=patent(id);if(!p.getUserId().equals(actor))throw new SecurityException("无权操作该专利");return p;}private Patent patent(Long id){return patentRepo.findById(id).orElseThrow(()->new IllegalArgumentException("专利不存在"));}
 private void require(String actual,String...allowed){for(String x:allowed)if(x.equals(actual))return;throw new IllegalStateException("当前状态不允许此操作: "+actual);}
 private void validateSource(Long patentId,String type,Long id){if("DISCLOSURE".equals(type)&&id!=null){PatentDisclosure d=disclosureRepo.findById(id).orElseThrow(()->new IllegalArgumentException("技术交底不存在"));if(!patentId.equals(d.getPatentId()))throw new IllegalArgumentException("技术交底不属于当前专利");}if("RESEARCH_DELIVERABLE".equals(type)&&id==null)throw new IllegalArgumentException("科研成果来源必须填写 sourceId");}
 private PatentMaterialCard toCard(Long patentId,Integer no,Integer version,MaterialCardRequest r){return PatentMaterialCard.builder().patentId(patentId).cardNo(no).versionNo(version).category(r.category()).title(r.title()).technicalProblemSummary(r.technicalProblemSummary()).technicalSolutionSummary(r.technicalSolutionSummary()).innovations(r.innovations()).experimentalData(r.experimentalData()).technicalEffects(r.technicalEffects()).drawings(r.drawings()).keywords(r.keywords()).claimFeatures(r.claimFeatures()).sourceType(r.sourceType()).sourceId(r.sourceId()).createdBy(r.actorUserId()).currentVersion(true).build();}
 private PatentInventor toInventor(Long p,InventorRequest r){return PatentInventor.builder().patentId(p).userId(r.userId()).name(r.name()).institution(r.institution()).inventorOrder(r.inventorOrder()).firstInventor(Boolean.TRUE.equals(r.firstInventor())||r.inventorOrder()==1).contribution(r.contribution()).contactEmail(r.contactEmail()).contactPhone(r.contactPhone()).confirmationStatus("PENDING").build();}
 private void syncLegacyOrder(Long patentId){List<PatentInventor> all=inventorRepo.findByPatentIdOrderByInventorOrderAsc(patentId);Patent p=patent(patentId);p.setInventorOrder(all.stream().filter(x->Boolean.TRUE.equals(x.getFirstInventor())).map(PatentInventor::getInventorOrder).findFirst().orElse(all.isEmpty()?null:all.getFirst().getInventorOrder()));patentRepo.save(p);}
 private String join(List<String>v){return v==null||v.isEmpty()?null:String.join(",",v);}
}
